}
function lossCarry(st, cost, proceeds) { if (!st.life) return 0; const r = capitalGainsTax({ cost, proceeds, mode: 'nominal', lossCarry: st.life.lossCarry || 0 }); st.life.lossCarry = r.lossCarryOut; return r.tax; }
