  const M = MK(st); ring(M.grave, { id: c.id, key: c.key, name: c.name, tk: c.tk, sector: c.sector, peakPx: c.peakPx, endPx: c.endPx, endedM: c.endedM, reason: c.status, cand: c.cand.slice(-RING.graveCand) }, RING.grave);
